#!/usr/bin/env python3
"""Write data/euc-jp.txt from the glibc iconv EUC-JP conversion."""

import subprocess
import sys
from pathlib import Path

BATCH = 256
HEADER = [
    "# EUC-JP vs Unicode mapping table, generated by tools/gen-euc-jp.py from glibc iconv EUC-JP.",
    "# Do not edit. Regenerate with: python3 tools/gen-euc-jp.py",
]
USAGE = "usage: gen-euc-jp.py [--check]\n"
ICONV_ERROR = "error: iconv\n"
OUT_OF_DATE = "data/euc-jp.txt is out of date\n"


class ConversionError(Exception):
    pass


def iconv(from_encoding, to_encoding, records):
    payload = b"".join(record + b"\n" for record in records)
    try:
        result = subprocess.run(
            ["iconv", "-c", "-f", from_encoding, "-t", to_encoding],
            input=payload,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
    except OSError as exc:
        raise ConversionError from exc
    if result.returncode not in (0, 1) or result.stderr:
        raise ConversionError
    if not result.stdout.endswith(b"\n"):
        raise ConversionError
    pieces = result.stdout.split(b"\n")[:-1]
    if len(pieces) != len(records):
        raise ConversionError
    return pieces


def candidate_codes():
    codes = [bytes((0x8E, b)) for b in range(0xA1, 0xFF)]
    codes += [bytes((a, b)) for a in range(0xA1, 0xFF) for b in range(0xA1, 0xFF)]
    codes += [bytes((0x8F, a, b)) for a in range(0xA1, 0xFF) for b in range(0xA1, 0xFF)]
    return codes


def mapping_text():
    records = {bytes((b,)): chr(b) for b in range(0x80)}
    codes = candidate_codes()
    texts = []
    for start in range(0, len(codes), BATCH):
        for piece in iconv("EUC-JP", "UTF-8", codes[start : start + BATCH]):
            try:
                texts.append(piece.decode("utf-8"))
            except UnicodeDecodeError as exc:
                raise ConversionError from exc

    eligible = [
        (code, text) for code, text in zip(codes, texts) if len(text) == 1
    ]
    for start in range(0, len(eligible), BATCH):
        batch = eligible[start : start + BATCH]
        pieces = iconv(
            "UTF-8", "EUC-JP", [text.encode("utf-8") for _, text in batch]
        )
        for (code, text), piece in zip(batch, pieces):
            if piece == code:
                records[code] = text

    lines = list(HEADER)
    for code in sorted(records, key=lambda value: int.from_bytes(value, "big")):
        lines.append(
            "0x%0*X\tU+%04X"
            % (len(code) * 2, int.from_bytes(code, "big"), ord(records[code]))
        )
    return "\n".join(lines) + "\n", len(records)


def main(argv):
    path = Path(__file__).resolve().parent.parent / "data" / "euc-jp.txt"
    if argv == []:
        try:
            text, count = mapping_text()
        except ConversionError:
            sys.stderr.write(ICONV_ERROR)
            return 1
        path.write_bytes(text.encode("utf-8"))
        print(f"wrote {count} mappings")
        return 0
    if argv == ["--check"]:
        try:
            text, _ = mapping_text()
        except ConversionError:
            sys.stderr.write(ICONV_ERROR)
            return 1
        try:
            current = path.read_bytes()
        except FileNotFoundError:
            current = None
        if current == text.encode("utf-8"):
            return 0
        sys.stderr.write(OUT_OF_DATE)
        return 1
    sys.stderr.write(USAGE)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
